// PROJETO SM3 — deterministic pre-curation for visual project pass.
const rows = $input.all().map(i => i.json);

function n(v) {
  const x = Number(v);
  return Number.isFinite(x) ? x : 0;
}

const eligible = rows.filter(r =>
  String(r.ANALYSIS_STATUS || '').toUpperCase() === 'ANALYZED' &&
  String(r.STORAGE_STATUS || '').toUpperCase() === 'ONLINE' &&
  String(r.ID_PROJETO || '').trim()
);

const projects = {};

for (const r of eligible) {
  const pid = r.ID_PROJETO;
  if (!projects[pid]) projects[pid] = [];

  const editorial = n(r.EDITORIAL_SCORE);
  const technical = n(r.TECHNICAL_SCORE);
  const composition = n(r.COMPOSITION_SCORE);
  const visibility = n(r.TATTOO_VISIBILITY);

  const weighted =
    editorial * 0.45 +
    technical * 0.20 +
    composition * 0.20 +
    visibility * 0.15;

  const triage = String(r.TRIAGEM || '').toUpperCase();
  const triageAdjust =
    triage === 'SELECIONADO' ? 5 :
    triage === 'DESCARTAR' ? -30 : 0;

  const kind = String(r.TIPO || '').toUpperCase().includes('VÍDEO') ||
               String(r.TIPO || '').toUpperCase().includes('VIDEO')
    ? 'video'
    : 'image';

  const analysisPath = kind === 'video'
    ? `/data/media/contact_sheets/${pid}/${r.ID_MIDIA}.jpg`
    : `/data/media/proxies/${pid}/${r.ID_MIDIA}.jpg`;

  projects[pid].push({
    media_id: r.ID_MIDIA,
    kind,
    analysis_path: analysisPath,
    stage: r.ANALYSIS_STAGE || '',
    shot_type: r.SHOT_TYPE || '',
    editorial_score: editorial,
    technical_score: technical,
    composition_score: composition,
    tattoo_visibility: visibility,
    analysis_confidence: n(r.ANALYSIS_CONFIDENCE),
    recommended_use: r.USAR_EM || '',
    best_moment: r.MELHOR_TRECHO || '',
    visual_summary: r['CONTEÚDO_VISUAL'] || '',
    redundancy_hint: r.REDUNDANCY_HINT || '',
    precuation_score: Math.round(weighted + triageAdjust)
  });
}

const output = [];

for (const [pid, media] of Object.entries(projects)) {
  media.sort((a, b) =>
    b.precuation_score - a.precuation_score ||
    b.analysis_confidence - a.analysis_confidence ||
    String(a.media_id).localeCompare(String(b.media_id))
  );

  const shortlist = media.slice(0, Math.min(12, media.length));

  output.push({
    json: {
      project_id: pid,
      candidate_count: shortlist.length,
      candidates: shortlist,
      context:
        'Curadoria editorial de projeto de tatuagem. Evitar quase-duplicatas. Preservar progressão narrativa e variedade visual.',
      dry_run: true
    }
  });
}

return output.length
  ? output
  : [{json:{dry_run:true,no_work:true,message:'Nenhum projeto possui mídia ANALYZED + ONLINE.'}}];

return $input.all().map(i => {
  const x = i.json;
  const c = x.curation || {};

  return {
    json: {
      dry_run: true,
      project_id: x.project_id,
      candidate_count: x.candidate_count,
      provider: x.provider,
      model: x.model,
      panel_path: x.panel_path,
      hero_id: c.hero_id,
      selected_ids: c.selected_ids || [],
      reserve_ids: c.reserve_ids || [],
      discard_ids: c.discard_ids || [],
      carousel_order: c.carousel_order || [],
      reel_candidate_ids: c.reel_candidate_ids || [],
      redundancy_groups: c.redundancy_groups || [],
      narrative: c.narrative || '',
      confidence: c.confidence,
      validated: true
    }
  };
});
